func extractToVulnInfos(pkgName string, cves []WpCveInfo) (vinfos []models.VulnInfo) {
	for _, vulnerability := range cves {
		cveID := fmt.Sprintf("WPVDBID-%s", vulnerability.ID)
		if len(vulnerability.References.Cve) == 0 {
			// Keep the WPScan ID when no CVE has been assigned.
		} else {
			cveID = "CVE-" + vulnerability.References.Cve[0]
		}

		var refs []models.Reference
		for _, url := range vulnerability.References.URL {
			refs = append(refs, models.Reference{
				Link: url,
			})
		}

		optional := map[string]string{}
		if vulnerability.Poc != "" {
			optional["poc"] = vulnerability.Poc
		}
		if vulnerability.IntroducedIn != "" {
			optional["introduced_in"] = vulnerability.IntroducedIn
		}

		content := models.CveContent{
			Type:         models.WpScan,
			CveID:        cveID,
			Title:        vulnerability.Title,
			Summary:      vulnerability.Description,
			References:   refs,
			Published:    vulnerability.CreatedAt.UTC(),
			LastModified: vulnerability.UpdatedAt.UTC(),
			Optional:     optional,
		}
		if vulnerability.Cvss != nil {
			content.Cvss3Score = vulnerability.Cvss.Score
